import { SAFE_AGENT_SESSION_ID } from "./cloudReplay/constants.js";
const REPLAY_COMMAND = /bitfab[-_ .]?replay|\bcmd\/registry\b/i;
const ALREADY_TAGGED = /AGENT_SESSION_ID|--agent-session-id/;
export function tagReplayCommand(command, agentSessionId) {
    if (!REPLAY_COMMAND.test(command) ||
        ALREADY_TAGGED.test(command) ||
        !SAFE_AGENT_SESSION_ID.test(agentSessionId)) {
        return null;
    }
    return `export AGENT_SESSION_ID='${agentSessionId}'; ${command}`;
}
